package control

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/json"
	"fmt"

	"omb/internal/autoinstall"
)

// CreateUbuntuAutoinstall persists only a validated normalized constructor result.
// The generated bytes must match the preview exactly; no update operation exists.
func (s Store) CreateUbuntuAutoinstall(ctx context.Context, file UbuntuAutoinstallFile) (UbuntuAutoinstallFile, error) {
	if !safeMenuText(file.Title, 80) {
		return UbuntuAutoinstallFile{}, fmt.Errorf("invalid Autoinstall title")
	}
	if file.State != "validated" {
		return UbuntuAutoinstallFile{}, fmt.Errorf("Autoinstall file must be validated")
	}
	rendered, err := autoinstall.Render(file.Values)
	if err != nil {
		return UbuntuAutoinstallFile{}, err
	}
	if !bytes.Equal(rendered, file.UserData) || fmt.Sprintf("%x", sha256.Sum256(file.UserData)) != file.SHA256 {
		return UbuntuAutoinstallFile{}, fmt.Errorf("Autoinstall content does not match its values and digest")
	}
	values, err := json.Marshal(file.Values)
	if err != nil {
		return UbuntuAutoinstallFile{}, err
	}
	err = s.Pool.QueryRow(ctx, `INSERT INTO ubuntu_autoinstall_files(title,"values",user_data,sha256,state,disk_mode,disk_serial) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING id,created_at`, file.Title, values, file.UserData, file.SHA256, file.State, file.Values.DiskMode, file.Values.DiskSerial).Scan(&file.ID, &file.CreatedAt)
	if err != nil {
		return UbuntuAutoinstallFile{}, err
	}
	return file, nil
}

func (s Store) UbuntuAutoinstalls(ctx context.Context) ([]UbuntuAutoinstallSummary, error) {
	rows, err := s.Pool.Query(ctx, `SELECT id,title,sha256,state,disk_mode,disk_serial,created_at FROM ubuntu_autoinstall_files ORDER BY id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	files := []UbuntuAutoinstallSummary{}
	for rows.Next() {
		var file UbuntuAutoinstallSummary
		if err := rows.Scan(&file.ID, &file.Title, &file.SHA256, &file.State, &file.DiskMode, &file.DiskSerial, &file.CreatedAt); err != nil {
			return nil, err
		}
		files = append(files, file)
	}
	return files, rows.Err()
}

func (s Store) UbuntuAutoinstall(ctx context.Context, id int64) (UbuntuAutoinstallFile, error) {
	var file UbuntuAutoinstallFile
	var values []byte
	err := s.Pool.QueryRow(ctx, `SELECT id,title,"values",user_data,sha256,state,created_at FROM ubuntu_autoinstall_files WHERE id=$1`, id).Scan(&file.ID, &file.Title, &values, &file.UserData, &file.SHA256, &file.State, &file.CreatedAt)
	if err != nil {
		return UbuntuAutoinstallFile{}, err
	}
	if err := json.Unmarshal(values, &file.Values); err != nil {
		return UbuntuAutoinstallFile{}, err
	}
	return file, nil
}
